-- Point every trainer back at the list it had before the apply, then
-- remove the copies (only the copies' own number range is touched) and
-- the saved links. Safe when the apply never ran: the CREATE makes an
-- empty saved-links table, and nothing matches.
CREATE TABLE IF NOT EXISTS `wow_chat_e014_snapshot_creature_default_trainer` LIKE `creature_default_trainer`;
UPDATE `creature_default_trainer` d JOIN `wow_chat_e014_snapshot_creature_default_trainer` s ON s.`CreatureId` = d.`CreatureId`
    SET d.`TrainerId` = s.`TrainerId`;
DELETE FROM `trainer_spell` WHERE `TrainerId` BETWEEN 1000000 AND 1999999;
DELETE FROM `trainer`       WHERE `Id`        BETWEEN 1000000 AND 1999999;
DROP TABLE `wow_chat_e014_snapshot_creature_default_trainer`;
